//go:build live

package ws

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"testing"
	"time"

	"github.com/coder/websocket"
	"github.com/coder/websocket/wsjson"
)

func TestLiveFramesAgainstRunningBridge(t *testing.T) {
	token := os.Getenv("BRIDGE_TOKEN")
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	conn, _, err := websocket.Dial(ctx, "ws://127.0.0.1:47899/ws", &websocket.DialOptions{
		HTTPHeader: map[string][]string{"Authorization": {"Bearer " + token}},
	})
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close(websocket.StatusNormalClosure, "")
	conn.SetReadLimit(8 << 20)
	send := func(id, method string, params map[string]any) {
		if err := wsjson.Write(ctx, conn, map[string]any{"id": id, "method": method, "params": params}); err != nil {
			t.Fatal(err)
		}
	}
	send("1", "surface.frames.subscribe", map[string]any{"surface_id": os.Getenv("PANE")})
	frames, full, bytes := 0, 0, 0
	deadline := time.Now().Add(4 * time.Second)
	for time.Now().Before(deadline) {
		rctx, rcancel := context.WithDeadline(ctx, deadline)
		var msg map[string]any
		err := wsjson.Read(rctx, conn, &msg)
		rcancel()
		if err != nil {
			break
		}
		if msg["id"] == "1" {
			b, _ := json.Marshal(msg)
			fmt.Println("subscribe response:", string(b))
			continue
		}
		switch msg["type"] {
		case "surface.frame":
			d := msg["data"].(map[string]any)
			frames++
			if d["full"] == true {
				full++
			}
			bytes += len(d["bytes"].(string))
			if frames <= 3 {
				fmt.Printf("frame seq=%v full=%v %vx%v\n", d["seq"], d["full"], d["width"], d["height"])
			}
		case "surface.frames.ended":
			fmt.Println("ended:", msg["data"])
		case "connected":
			b, _ := json.Marshal(msg["data"].(map[string]any)["capabilities"])
			fmt.Println("capabilities:", string(b))
		}
	}
	fmt.Printf("received %d frames (%d full, %d base64 bytes) in 4s\n", frames, full, bytes)
	send("2", "surface.frames.unsubscribe", map[string]any{"surface_id": os.Getenv("PANE")})
	for i := 0; i < 20; i++ {
		var msg map[string]any
		if err := wsjson.Read(ctx, conn, &msg); err != nil {
			break
		}
		if msg["id"] == "2" || msg["type"] == "surface.frames.ended" {
			b, _ := json.Marshal(msg)
			fmt.Println("after unsubscribe:", string(b))
			if msg["type"] == "surface.frames.ended" {
				break
			}
		}
	}
	if frames == 0 || full == 0 {
		t.Fatalf("expected at least one full frame, got frames=%d full=%d", frames, full)
	}
}
EOF
